/**
 * MERQBA - Tasa USD/CUP individual por vendedor.
 * Compatible con Dokan Lite 5.3.4, WooCommerce 11.2.2 y FOX/WOOCS 1.5.7.
 * Instalar como un único snippet PHP (sin etiqueta de apertura adicional si Code Snippets la añade).
 *
 * Funcionamiento:
 * - El vendedor configura su tasa USD/CUP en Dokan > Ajustes de la tienda.
 * - La tasa no puede ser inferior a la tasa CUP configurada en FOX.
 * - Al seleccionar CUP, cada producto usa la tasa de su vendedor.
 * - Si un vendedor no configura tasa, se utiliza la tasa global de FOX.
 * - No modifica las opciones internas ni los archivos de Dokan, WooCommerce o FOX.
 *
 * IMPORTANTE: FOX debe estar en modo de múltiples monedas (woocs_is_multiple_allowed).
 * La moneda base de WooCommerce debe ser USD y la moneda de destino debe ser CUP.
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

if ( ! defined( 'MERQBA_RATE_META' ) ) {
    define( 'MERQBA_RATE_META', '_merqba_usd_cup_rate' );
}

/* --------------------------------------------------------------------------
 * 1. UTILIDADES Y TASAS
 * -------------------------------------------------------------------------- */

if ( ! function_exists( 'merqba_normalize_exchange_rate' ) ) {
    function merqba_normalize_exchange_rate( $rate ) {
        if ( is_array( $rate ) || is_object( $rate ) ) {
            return false;
        }

        $rate = trim( (string) $rate );

        if ( '' === $rate || ! is_numeric( $rate ) ) {
            return false;
        }

        $rate = (float) $rate;

        if ( ! is_finite( $rate ) || $rate <= 0 || $rate > 1000000 ) {
            return false;
        }

        return $rate;
    }
}

/** Devuelve la tasa CUP que FOX aplica realmente a la conversión USD -> CUP. */
if ( ! function_exists( 'merqba_get_fox_cup_rate' ) ) {
    function merqba_get_fox_cup_rate() {
        global $WOOCS;

        $currencies = array();

        if ( is_object( $WOOCS ) && method_exists( $WOOCS, 'get_currencies' ) ) {
            $currencies = $WOOCS->get_currencies();
        }

        if ( ! is_array( $currencies ) || empty( $currencies ) ) {
            $currencies = get_option( 'woocs', array() );
        }

        if ( ! is_array( $currencies ) ) {
            return false;
        }

        // En FOX 1.5.7 las monedas normalmente están indexadas por su código: USD, CUP, etc.
        if ( isset( $currencies['CUP']['rate'] ) ) {
            return merqba_normalize_exchange_rate( $currencies['CUP']['rate'] );
        }

        // Compatibilidad con instalaciones cuya estructura no esté indexada por código.
        foreach ( $currencies as $currency ) {
            if ( ! is_array( $currency ) ) {
                continue;
            }

            $code = '';
            if ( isset( $currency['name'] ) ) {
                $code = strtoupper( (string) $currency['name'] );
            } elseif ( isset( $currency['code'] ) ) {
                $code = strtoupper( (string) $currency['code'] );
            }

            if ( 'CUP' === $code && isset( $currency['rate'] ) ) {
                return merqba_normalize_exchange_rate( $currency['rate'] );
            }
        }

        return false;
    }
}

if ( ! function_exists( 'merqba_get_vendor_exchange_rate' ) ) {
    function merqba_get_vendor_exchange_rate( $vendor_id ) {
        $rate = get_user_meta( absint( $vendor_id ), MERQBA_RATE_META, true );
        return merqba_normalize_exchange_rate( $rate );
    }
}

/**
 * Devuelve la tasa individual efectiva. Si el vendedor no tiene tasa o su tasa
 * quedó por debajo de la nueva tasa mínima de FOX, se devuelve false y FOX usa
 * su conversión global.
 */
if ( ! function_exists( 'merqba_get_effective_vendor_rate' ) ) {
    function merqba_get_effective_vendor_rate( $vendor_id ) {
        $vendor_rate = merqba_get_vendor_exchange_rate( $vendor_id );
        $fox_rate    = merqba_get_fox_cup_rate();

        if ( false === $vendor_rate || false === $fox_rate || $vendor_rate < $fox_rate ) {
            return false;
        }

        return $vendor_rate;
    }
}

if ( ! function_exists( 'merqba_validate_vendor_exchange_rate' ) ) {
    function merqba_validate_vendor_exchange_rate( $rate ) {
        $rate = merqba_normalize_exchange_rate( $rate );

        if ( false === $rate ) {
            return new WP_Error(
                'merqba_invalid_vendor_rate',
                'Introduce una tasa numérica válida mayor que cero.'
            );
        }

        $fox_rate = merqba_get_fox_cup_rate();

        if ( false === $fox_rate ) {
            return new WP_Error(
                'merqba_fox_rate_missing',
                'El administrador todavía no ha configurado la tasa CUP en FOX.'
            );
        }

        if ( $rate < $fox_rate ) {
            return new WP_Error(
                'merqba_vendor_rate_too_low',
                sprintf(
                    'Tu tasa no puede ser inferior a la tasa mínima de Merqba: %s CUP por USD.',
                    number_format_i18n( $fox_rate, 2 )
                )
            );
        }

        return $rate;
    }
}

/** Comprueba que FOX está activo en CUP y en modo de múltiples monedas. */
if ( ! function_exists( 'merqba_can_apply_vendor_conversion' ) ) {
    function merqba_can_apply_vendor_conversion() {
        global $WOOCS;

        if ( ! is_object( $WOOCS ) || ! isset( $WOOCS->current_currency ) ) {
            return false;
        }

        // En FOX 1.5.7 los filtros que reciben el objeto producto se registran en este modo.
        if ( empty( $WOOCS->is_multiple_allowed ) ) {
            return false;
        }

        // La tasa que guardamos es CUP por USD; la moneda base debe ser USD.
        if ( 'USD' !== strtoupper( (string) get_option( 'woocommerce_currency', 'USD' ) ) ) {
            return false;
        }

        $current_currency = strtoupper( (string) $WOOCS->current_currency );

        // FOX admite una moneda explícita en esta petición; respetarla también.
        if ( isset( $_REQUEST['woocs_raw_woocommerce_price_currency'] ) && is_string( $_REQUEST['woocs_raw_woocommerce_price_currency'] ) ) {
            $requested = strtoupper( sanitize_text_field( wp_unslash( $_REQUEST['woocs_raw_woocommerce_price_currency'] ) ) );
            if ( 'CUP' === $requested ) {
                $current_currency = 'CUP';
            }
        }

        if ( 'CUP' !== $current_currency ) {
            return false;
        }

        // No convertir precios dentro del editor administrativo normal.
        if ( is_admin() && ! ( function_exists( 'wp_doing_ajax' ) && wp_doing_ajax() ) ) {
            return false;
        }

        return false !== merqba_get_fox_cup_rate();
    }
}

/** Obtiene el ID del vendedor, incluyendo productos variables y variaciones. */
if ( ! function_exists( 'merqba_get_product_vendor_id' ) ) {
    function merqba_get_product_vendor_id( $product ) {
        if ( ! $product instanceof WC_Product ) {
            return 0;
        }

        if ( function_exists( 'dokan_get_vendor_by_product' ) ) {
            return absint( dokan_get_vendor_by_product( $product, true ) );
        }

        $product_id = $product->get_id();
        $vendor_id  = absint( get_post_field( 'post_author', $product_id ) );

        if ( ! $vendor_id && $product->is_type( 'variation' ) ) {
            $vendor_id = absint( get_post_field( 'post_author', $product->get_parent_id() ) );
        }

        return $vendor_id;
    }
}

/* --------------------------------------------------------------------------
 * 2. CAMPO EN DOKAN LITE 5.3.4
 * -------------------------------------------------------------------------- */

add_filter( 'dokan_get_vendor_settings_schema', 'merqba_add_vendor_exchange_rate_field', 90, 2 );

if ( ! function_exists( 'merqba_add_vendor_exchange_rate_field' ) ) {
    function merqba_add_vendor_exchange_rate_field( $elements, $vendor_id ) {
        if ( ! is_array( $elements ) ) {
            return $elements;
        }

        $vendor_id   = absint( $vendor_id );
        $stored_rate = merqba_get_vendor_exchange_rate( $vendor_id );
        $fox_rate    = merqba_get_fox_cup_rate();

        $description = false !== $fox_rate
            ? sprintf(
                'La tasa mínima de Merqba es %s CUP por USD. Tu tasa no puede ser inferior.',
                number_format_i18n( $fox_rate, 2 )
            )
            : 'El administrador todavía no ha configurado la tasa CUP en FOX.';

        $elements[] = array(
            'id'          => 'merqba_exchange_rate_section',
            'type'        => 'section',
            'subpage_id'  => 'store_settings',
            'tab_id'      => 'tab_general',
            'title'       => 'Tasa de cambio USD/CUP',
            'description' => 'Configura la tasa que FOX utilizará para mostrar en CUP los productos de tu tienda. Las compras siguen el flujo de moneda y pago configurado en FOX.',
            'collapsible' => true,
            'priority'    => 95,
        );

        $elements[] = array(
            'id'          => 'merqba_usd_cup_rate',
            'type'        => 'field',
            'variant'     => 'number',
            'section_id'  => 'merqba_exchange_rate_section',
            'title'       => 'Tu tasa USD/CUP',
            'description' => $description,
            'placeholder' => 'Ejemplo: 500',
            'value'       => false !== $stored_rate ? (string) $stored_rate : '',
            'default'     => '',
            'layout'      => 'full-width',
            'non_meta'    => true,
            'min'         => 0.01,
            'step'        => 0.01,
            'sanitize_callback' => static function ( $value ) {
                if ( null === $value || '' === trim( (string) $value ) ) {
                    return '';
                }

                $rate = merqba_normalize_exchange_rate( $value );

                if ( false === $rate ) {
                    return '__MERQBA_INVALID_RATE__';
                }

                return number_format( $rate, 8, '.', '' );
            },
            'validation_func' => static function ( $value, $all_values = array(), $vendor_id = 0 ) {
                if ( '' === $value || null === $value ) {
                    return true;
                }

                if ( '__MERQBA_INVALID_RATE__' === $value ) {
                    return 'Introduce una tasa numérica válida mayor que cero.';
                }

                $validated = merqba_validate_vendor_exchange_rate( $value );
                return is_wp_error( $validated ) ? $validated->get_error_message() : true;
            },
        );

        return $elements;
    }
}

/* --------------------------------------------------------------------------
 * 3. GUARDADO DE LA TASA EN user_meta
 * -------------------------------------------------------------------------- */

add_action( 'dokan_after_saving_vendor_settings', 'merqba_save_vendor_exchange_rate', 20, 3 );

if ( ! function_exists( 'merqba_save_vendor_exchange_rate' ) ) {
    function merqba_save_vendor_exchange_rate( $vendor_id, $sanitized_values, $fields_by_id = array() ) {
        $vendor_id = absint( $vendor_id );

        if ( ! $vendor_id || ! is_array( $sanitized_values ) || ! array_key_exists( 'merqba_usd_cup_rate', $sanitized_values ) ) {
            return;
        }

        if ( ! current_user_can( 'manage_woocommerce' ) && get_current_user_id() !== $vendor_id ) {
            return;
        }

        $raw_rate = $sanitized_values['merqba_usd_cup_rate'];

        if ( '' === $raw_rate || null === $raw_rate ) {
            delete_user_meta( $vendor_id, MERQBA_RATE_META );
            return;
        }

        if ( '__MERQBA_INVALID_RATE__' === $raw_rate ) {
            return;
        }

        $validated_rate = merqba_validate_vendor_exchange_rate( $raw_rate );

        if ( is_wp_error( $validated_rate ) ) {
            return;
        }

        update_user_meta(
            $vendor_id,
            MERQBA_RATE_META,
            number_format( $validated_rate, 8, '.', '' )
        );
    }
}

/* --------------------------------------------------------------------------
 * 4. INTEGRACIÓN REAL CON FOX: PRECIO POR PRODUCTO/VENDEDOR
 * -------------------------------------------------------------------------- */

/**
 * Convierte el importe base USD con la tasa del vendedor antes del filtro de FOX.
 * Se marca el producto para que woocs_skip_conversion impida la segunda conversión.
 */
if ( ! function_exists( 'merqba_preconvert_product_price' ) ) {
    function merqba_preconvert_product_price( $price, $product = null ) {
        if ( ! merqba_can_apply_vendor_conversion() || ! $product instanceof WC_Product || ! is_numeric( $price ) ) {
            return $price;
        }

        $vendor_id = merqba_get_product_vendor_id( $product );
        $rate      = merqba_get_effective_vendor_rate( $vendor_id );

        if ( false === $rate ) {
            return $price; // FOX aplica su tasa global normalmente.
        }

        $product_key = spl_object_id( $product );
        if ( ! isset( $GLOBALS['merqba_woocs_preconverted_products'] ) || ! is_array( $GLOBALS['merqba_woocs_preconverted_products'] ) ) {
            $GLOBALS['merqba_woocs_preconverted_products'] = array();
        }
        $GLOBALS['merqba_woocs_preconverted_products'][ $product_key ] = true;

        return (float) $price * (float) $rate;
    }
}

// FOX 1.5.7 registra sus filtros de producto en prioridad 9999; usamos 9998 para preparar el importe.
$merqba_product_price_hooks = array(
    'woocommerce_product_get_price',
    'woocommerce_product_get_regular_price',
    'woocommerce_product_get_sale_price',
    'woocommerce_product_variation_get_price',
    'woocommerce_product_variation_get_regular_price',
    'woocommerce_product_variation_get_sale_price',
    'woocommerce_get_variation_regular_price',
    'woocommerce_get_variation_sale_price',
);

foreach ( $merqba_product_price_hooks as $merqba_hook ) {
    add_filter( $merqba_hook, 'merqba_preconvert_product_price', 9998, 4 );
}

/**
 * FOX llama este filtro al principio de raw_woocommerce_price(). Solo omitimos
 * su conversión cuando acabamos de convertir ese mismo objeto producto.
 */
add_filter( 'woocs_skip_conversion', 'merqba_skip_fox_second_conversion', 10, 3 );

if ( ! function_exists( 'merqba_skip_fox_second_conversion' ) ) {
    function merqba_skip_fox_second_conversion( $skip, $price = null, $product = null ) {
        if ( $skip || ! $product instanceof WC_Product || ! isset( $GLOBALS['merqba_woocs_preconverted_products'] ) ) {
            return $skip;
        }

        $product_key = spl_object_id( $product );

        if ( empty( $GLOBALS['merqba_woocs_preconverted_products'][ $product_key ] ) ) {
            return $skip;
        }

        unset( $GLOBALS['merqba_woocs_preconverted_products'][ $product_key ] );
        return true;
    }
}

/**
 * FOX 1.5.7 convierte las matrices de precios variables con woocs_exchange_value()
 * (sin pasar por woocs_skip_conversion). Ajustamos cada variación por la relación
 * tasa_vendedor / tasa_FOX antes de que FOX aplique su tasa global.
 */
add_filter( 'woocommerce_variation_prices', 'merqba_adjust_variation_prices_for_vendor', 9998, 3 );

if ( ! function_exists( 'merqba_adjust_variation_prices_for_vendor' ) ) {
    function merqba_adjust_variation_prices_for_vendor( $prices_array, $variable_product = null, $for_display = false ) {
        if ( ! merqba_can_apply_vendor_conversion() || ! is_array( $prices_array ) || ! $variable_product instanceof WC_Product ) {
            return $prices_array;
        }

        $fox_rate = merqba_get_fox_cup_rate();
        if ( false === $fox_rate || $fox_rate <= 0 ) {
            return $prices_array;
        }

        foreach ( $prices_array as $price_type => $variation_prices ) {
            if ( ! is_array( $variation_prices ) ) {
                continue;
            }

            foreach ( $variation_prices as $variation_id => $price ) {
                $vendor_id = function_exists( 'dokan_get_vendor_by_product' )
                    ? absint( dokan_get_vendor_by_product( absint( $variation_id ), true ) )
                    : absint( get_post_field( 'post_author', $variable_product->get_id() ) );

                $vendor_rate = merqba_get_effective_vendor_rate( $vendor_id );

                if ( false !== $vendor_rate && is_numeric( $price ) ) {
                    $prices_array[ $price_type ][ $variation_id ] = (float) $price * ( (float) $vendor_rate / (float) $fox_rate );
                }
            }
        }

        return $prices_array;
    }
}

/** Evita que la caché de precios variables mezcle tasas distintas. */
add_filter( 'woocommerce_get_variation_prices_hash', 'merqba_add_vendor_rate_to_variation_hash', 9998, 3 );

if ( ! function_exists( 'merqba_add_vendor_rate_to_variation_hash' ) ) {
    function merqba_add_vendor_rate_to_variation_hash( $price_hash, $product, $for_display ) {
        if ( ! is_array( $price_hash ) || ! $product instanceof WC_Product || ! merqba_can_apply_vendor_conversion() ) {
            return $price_hash;
        }

        $vendor_id = merqba_get_product_vendor_id( $product );
        $rate      = merqba_get_effective_vendor_rate( $vendor_id );

        $price_hash['merqba_vendor_cup_rate'] = false !== $rate ? (string) $rate : 'fox-global';
        return $price_hash;
    }
}

/* --------------------------------------------------------------------------
 * 5. MOSTRAR LA TASA INFORMATIVA EN LA TIENDA DEL VENDEDOR
 * -------------------------------------------------------------------------- */

if ( ! function_exists( 'merqba_render_vendor_rate' ) ) {
    function merqba_render_vendor_rate( $vendor_id ) {
        $vendor_id = absint( $vendor_id );
        if ( ! $vendor_id ) {
            return '';
        }

        $rate = merqba_get_vendor_exchange_rate( $vendor_id );
        if ( false === $rate ) {
            return '';
        }

        $html  = '<div class="merqba-store-rate" style="background:#f6f7f7;border:1px solid #e2e2e2;border-radius:6px;padding:12px 16px;margin:0 0 20px;">';
        $html .= '<strong>' . esc_html__( 'Tasa de cambio del vendedor:', 'merqba' ) . '</strong> ';
        $html .= esc_html( sprintf( '1 USD = %s CUP', number_format_i18n( $rate, 2 ) ) );
        $html .= '<br><small>' . esc_html__( 'Los precios en CUP de sus productos utilizan esta tasa cuando está seleccionada esa moneda.', 'merqba' ) . '</small>';
        $html .= '</div>';

        return $html;
    }
}

add_action( 'dokan_store_page_info', 'merqba_show_rate_on_store_page', 20, 1 );

if ( ! function_exists( 'merqba_show_rate_on_store_page' ) ) {
    function merqba_show_rate_on_store_page( $store ) {
        $vendor_id = 0;

        if ( is_object( $store ) && method_exists( $store, 'get_id' ) ) {
            $vendor_id = absint( $store->get_id() );
        } elseif ( is_object( $store ) && isset( $store->ID ) ) {
            $vendor_id = absint( $store->ID );
        } elseif ( is_numeric( $store ) ) {
            $vendor_id = absint( $store );
        }

        echo merqba_render_vendor_rate( $vendor_id ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
    }
}

add_shortcode( 'merqba_tasa_usd_cup', 'merqba_vendor_rate_shortcode' );

if ( ! function_exists( 'merqba_vendor_rate_shortcode' ) ) {
    function merqba_vendor_rate_shortcode( $atts ) {
        $atts = shortcode_atts( array( 'vendor_id' => 0 ), $atts, 'merqba_tasa_usd_cup' );
        $vendor_id = absint( $atts['vendor_id'] );

        if ( ! $vendor_id && function_exists( 'dokan_is_store_page' ) && dokan_is_store_page() ) {
            $store_name = get_query_var( 'store' );

            if ( $store_name && function_exists( 'dokan_get_vendor_by_store_url' ) ) {
                $vendor_id = absint( dokan_get_vendor_by_store_url( $store_name ) );
            }
        }

        return $vendor_id ? merqba_render_vendor_rate( $vendor_id ) : '';
    }
}

/* --------------------------------------------------------------------------
 * 6. API REST PARA LA APLICACIÓN DE ADMINISTRACIÓN RÁPIDA
 * --------------------------------------------------------------------------
 * Endpoint: /wp-json/merqba/v1/vendor-rate
 * GET  : devuelve la tasa del vendedor autenticado y la tasa mínima de FOX.
 * POST : actualiza la tasa del vendedor autenticado.
 *
 * Seguridad:
 * - No recibe vendor_id: el usuario se obtiene de la sesión autenticada.
 * - Solo permite vendedores Dokan.
 * - Utiliza la autenticación REST ya configurada en WordPress (cookie + nonce,
 *   Application Passwords, JWT u otro proveedor REST instalado).
 * - La validación de la tasa se repite en el servidor.
 */

add_action( 'rest_api_init', 'merqba_register_vendor_rate_rest_routes' );

if ( ! function_exists( 'merqba_register_vendor_rate_rest_routes' ) ) {
    function merqba_register_vendor_rate_rest_routes() {
        register_rest_route(
            'merqba/v1',
            '/vendor-rate',
            array(
                array(
                    'methods'             => WP_REST_Server::READABLE,
                    'callback'            => 'merqba_rest_get_vendor_rate',
                    'permission_callback' => 'merqba_rest_vendor_rate_permission',
                ),
                array(
                    'methods'             => WP_REST_Server::CREATABLE,
                    'callback'            => 'merqba_rest_update_vendor_rate',
                    'permission_callback' => 'merqba_rest_vendor_rate_permission',
                    'args'                => array(
                        'rate' => array(
                            'required'          => true,
                            'description'       => 'Nueva tasa CUP por USD del vendedor autenticado.',
                            'type'              => array( 'string', 'number' ),
                            'sanitize_callback' => 'sanitize_text_field',
                        ),
                    ),
                ),
            )
        );
    }
}

/** Solo permite acceder a vendedores autenticados de Dokan. */
if ( ! function_exists( 'merqba_rest_vendor_rate_permission' ) ) {
    function merqba_rest_vendor_rate_permission( $request ) {
        $user_id = get_current_user_id();

        if ( ! $user_id || ! is_user_logged_in() ) {
            return new WP_Error(
                'merqba_rest_auth_required',
                'Debes iniciar sesión para consultar o modificar tu tasa.',
                array( 'status' => 401 )
            );
        }

        $is_vendor = false;

        if ( function_exists( 'dokan_is_user_seller' ) ) {
            $is_vendor = dokan_is_user_seller( $user_id );
        } else {
            $user      = get_userdata( $user_id );
            $is_vendor = $user && in_array( 'seller', (array) $user->roles, true );
        }

        if ( ! $is_vendor ) {
            return new WP_Error(
                'merqba_rest_vendor_only',
                'Esta función está disponible únicamente para vendedores autorizados.',
                array( 'status' => 403 )
            );
        }

        return true;
    }
}

/** Devuelve exclusivamente los datos de tasa del vendedor autenticado. */
if ( ! function_exists( 'merqba_rest_get_vendor_rate' ) ) {
    function merqba_rest_get_vendor_rate( $request ) {
        $vendor_id = get_current_user_id();
        $rate      = merqba_get_vendor_exchange_rate( $vendor_id );
        $fox_rate  = merqba_get_fox_cup_rate();

        return rest_ensure_response(
            array(
                'success'       => true,
                'vendor_id'     => $vendor_id,
                'configured'    => false !== $rate,
                'rate'          => false !== $rate ? number_format( $rate, 8, '.', '' ) : null,
                'minimum_rate'  => false !== $fox_rate ? number_format( $fox_rate, 8, '.', '' ) : null,
                'currency_from' => 'USD',
                'currency_to'   => 'CUP',
                'message'       => false !== $fox_rate
                    ? 'Tasa consultada correctamente.'
                    : 'FOX todavía no tiene configurada una tasa CUP válida.',
            )
        );
    }
}

/** Valida y guarda la tasa usando el user_meta que ya consume Dokan y FOX. */
if ( ! function_exists( 'merqba_rest_update_vendor_rate' ) ) {
    function merqba_rest_update_vendor_rate( $request ) {
        $vendor_id = get_current_user_id();
        $raw_rate  = $request->get_param( 'rate' );

        if ( is_array( $raw_rate ) || is_object( $raw_rate ) || '' === trim( (string) $raw_rate ) ) {
            return new WP_Error(
                'merqba_rest_invalid_rate',
                'Debes introducir una tasa numérica mayor que cero.',
                array( 'status' => 400 )
            );
        }

        $validated_rate = merqba_validate_vendor_exchange_rate( $raw_rate );

        if ( is_wp_error( $validated_rate ) ) {
            return new WP_Error(
                $validated_rate->get_error_code(),
                $validated_rate->get_error_message(),
                array( 'status' => 400 )
            );
        }

        $rate_to_save = number_format( $validated_rate, 8, '.', '' );
        update_user_meta( $vendor_id, MERQBA_RATE_META, $rate_to_save );

        // Verificar el valor persistido; update_user_meta puede devolver false si no cambió.
        $saved_rate = merqba_get_vendor_exchange_rate( $vendor_id );

        if ( false === $saved_rate || abs( $saved_rate - $validated_rate ) > 0.0000001 ) {
            return new WP_Error(
                'merqba_rest_save_failed',
                'No se pudo confirmar el guardado de la tasa. Inténtalo nuevamente.',
                array( 'status' => 500 )
            );
        }

        return rest_ensure_response(
            array(
                'success'      => true,
                'vendor_id'    => $vendor_id,
                'configured'   => true,
                'rate'         => number_format( $saved_rate, 8, '.', '' ),
                'minimum_rate' => number_format( merqba_get_fox_cup_rate(), 8, '.', '' ),
                'message'      => 'Tu tasa de cambio se actualizó correctamente.',
            )
        );
    }
}
